function packet(moduleId,op,payload,target={kind:"shell",id:"runtime"},scope="session"){return{id:crypto.randomUUID(),op,source:{kind:"module",id:moduleId},target,scope,flags:0,ts:Date.now(),payload}}
function record(p){term.recentPackets.push(p);if(term.recentPackets.length>80)term.recentPackets.shift()}
const enc=new TextEncoder,dec=new TextDecoder;
function mpEncode(v){const out=[];mpWrite(out,v);return new Uint8Array(out)}
function mpWrite(out,v){if(v===undefined||v===null)out.push(192);else if(typeof v==="boolean")out.push(v?195:194);else if(typeof v==="number"){if(Number.isInteger(v)&&v>=0&&v<=127)out.push(v);else if(Number.isInteger(v)&&v>=-32&&v<0)out.push(224|v+32);else if(Number.isInteger(v)&&v>=0&&v<=255)out.push(204,v);else if(Number.isInteger(v)&&v>=0&&v<=65535)u16(out,205,v);else if(Number.isInteger(v)&&v>=0&&v<=4294967295)out.push(206,v>>>24&255,v>>>16&255,v>>>8&255,v&255);else if(Number.isInteger(v)&&Number.isSafeInteger(v)){let b=BigInt(v);if(b<0)b=(1n<<64n)+b;out.push(211);for(let s=56n;s>=0n;s-=8n)out.push(Number(b>>s&255n))}else{const b=new Uint8Array(8);new DataView(b.buffer).setFloat64(0,v,false);out.push(203,...b)}}else if(typeof v==="string")mpStr(out,v);else if(Array.isArray(v)){v.length<16?out.push(144|v.length):u16(out,220,v.length);v.forEach(x=>mpWrite(out,x))}else{const entries=Object.entries(v).filter(([,x])=>x!==undefined);entries.length<16?out.push(128|entries.length):u16(out,222,entries.length);entries.forEach(([k,x])=>{mpStr(out,k);mpWrite(out,x)})}}
function mpStr(out,v){const b=enc.encode(v);b.length<32?out.push(160|b.length):b.length<=255?out.push(217,b.length):u16(out,218,b.length);out.push(...b)}
function u16(out,m,v){out.push(m,v>>>8&255,v&255)}
function mpDecode(buf){const r={data:buf instanceof Uint8Array?buf:new Uint8Array(buf),offset:0};return mpRead(r)}
function mpRead(r){const m=r.data[r.offset++];if(m<=127)return m;if(m>=224)return m-256;if((m&224)===160)return mpReadStr(r,m&31);if((m&240)===144)return Array.from({length:m&15},()=>mpRead(r));if((m&240)===128)return mpReadMap(r,m&15);if(m===192)return null;if(m===194)return false;if(m===195)return true;if(m===204)return r.data[r.offset++];if(m===205)return mpReadU16(r);if(m===206){const v=new DataView(r.data.buffer,r.data.byteOffset+r.offset,4).getUint32(0,false);r.offset+=4;return v}if(m===207)return mpRead64(r,false);if(m===208)return r.data[r.offset++]<<24>>24;if(m===209){const v=r.data[r.offset]<<8|r.data[r.offset+1];r.offset+=2;return v<<16>>16}if(m===210){const v=new DataView(r.data.buffer,r.data.byteOffset+r.offset,4).getInt32(0,false);r.offset+=4;return v}if(m===211)return mpRead64(r,true);if(m===203){const v=new DataView(r.data.buffer,r.data.byteOffset+r.offset,8).getFloat64(0,false);r.offset+=8;return v}if(m===217)return mpReadStr(r,r.data[r.offset++]);if(m===218)return mpReadStr(r,mpReadU16(r));if(m===220)return Array.from({length:mpReadU16(r)},()=>mpRead(r));if(m===222)return mpReadMap(r,mpReadU16(r));throw new Error(`Unsupported LMI binary marker 0x${m.toString(16)}`)}
function mpReadStr(r,len){const v=dec.decode(r.data.slice(r.offset,r.offset+len));r.offset+=len;return v}
function mpReadU16(r){const v=r.data[r.offset]<<8|r.data[r.offset+1];r.offset+=2;return v}
function mpRead64(r,signed){let v=0n;for(let i=0;i<8;i++)v=v<<8n|BigInt(r.data[r.offset++]);if(signed&&v&(1n<<63n))v-=1n<<64n;return Number(v)}
function mpReadMap(r,len){const o={};for(let i=0;i<len;i++){const k=mpRead(r);o[k]=mpRead(r)}return o}
function b64(v){let s="";mpEncode(v).forEach(x=>s+=String.fromCharCode(x));return btoa(s)}
function fromB64(v){const s=atob(v);return mpDecode(Uint8Array.from(s,c=>c.charCodeAt(0)))}
async function postJson(path,payload){const r=await fetch(`/api-r${path}`,{method:"POST",headers:{Accept:"application/json","Content-Type":"application/json"},body:JSON.stringify(payload),cache:"no-store"});const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||`request failed ${r.status}`);return body}
async function postPacket(p){record(p);const r=await fetch("/api-r/packet",{method:"POST",headers:{Accept:"application/x-msgpack","Content-Type":"application/x-msgpack"},body:mpEncode(p),cache:"no-store"});const body=mpDecode(await r.arrayBuffer());if(!r.ok)throw new Error(`binary packet failed ${r.status}`);record(body);return body}
function publish(moduleId,topic,payload){const p=packet(moduleId,Op.EVENT_PUBLISH,{topic,payload},undefined,"broadcast");record(p);(term.topics.get(topic)||[]).forEach(fn=>fn(payload,p))}
function subscribe(topic,fn){const list=term.topics.get(topic)||[];list.push(fn);term.topics.set(topic,list)}
async function setState(moduleId,key,value,{persist=false,scope="user"}={}){const p=packet(moduleId,Op.STATE_SET,{key,value,scope},persist?{kind:"server",id:"api-r"}:{kind:"shell",id:"runtime"},persist?"server":scope);term.values.set(key,value);record(p);if(persist)await postPacket(p)}
async function getState(moduleId,key,scope="user"){if(term.values.has(key))return term.values.get(key);const response=await postPacket(packet(moduleId,Op.STATE_GET,{key,scope},{kind:"server",id:"api-r"},"server"));const value=response.payload?.value;if(value!==undefined&&value!==null)term.values.set(key,value);return value??undefined}
function debugView(){return{registeredModules:modules.map(({id,name,capabilities})=>({id,name,capabilities})),recentPackets:term.recentPackets.slice(-20),knownTopics:[...term.topics.keys()].sort(),pendingRequestCount:0,stateKeys:[...term.values.keys()].sort()}}
function renderLogin(){root.innerHTML=`<main class="login-shell"><form id="loginForm" class="login-panel"><pre>${esc(BANNER.join("\n"))}</pre><h1>LMI-R Access Portal</h1><p>Use normal LMI credentials. On first login, LMI-R imports only username and password hash into the object store.</p><label>Username<input id="loginUser" autocomplete="username" required></label><label>Password<input id="loginPass" type="password" autocomplete="current-password" required></label><button type="submit">Log in</button><div class="login-status">${esc(term.statusText)}</div></form></main>`;const form=document.querySelector("#loginForm"),u=document.querySelector("#loginUser"),p=document.querySelector("#loginPass"),s=document.querySelector(".login-status");u?.focus();form?.addEventListener("submit",e=>{e.preventDefault();s.textContent="Authenticating...";postJson("/auth/login",{username:u.value,password:p.value}).then(body=>{user=body.user;sessionStorage.setItem("lmi-r:user",b64(user));seedFs();bootTerminal()}).catch(err=>s.textContent=String(err))})}
function renderTerminal(){root.innerHTML=`<main class="terminal-shell" data-theme="lmi-r-dark"><section class="terminal-window" aria-label="LMI-R terminal"><div id="terminalOutput" class="terminal-output">${term.lines.map(renderLine).join("")}</div><form id="terminalForm" class="terminal-input"><span>${esc(user.username)}@lmi-r:${esc(shortPwd(term.cwd))}$</span><input id="terminalCommand" autocomplete="off" spellcheck="false" autofocus><small id="terminalSuggestion">${esc(term.suggestion)}</small></form></section></main>`;wire()}
function renderLine(line){if(line.kind==="lfetch")return`<div class="term-line lfetch">${line.text}</div>`;return`<div class="term-line ${line.kind}">${line.kind==="input"?highlight(line.text):esc(line.text)}</div>`}
function activeApp(){if(term.activeApp==="settings")return`settings.demo.message\n${term.settingsValue}`;if(term.activeApp==="sift")return`${term.siftNote}\nTry: asset demo`;if(term.activeApp==="fleetline")return`Last selected asset\n${term.fleetlineAsset?`${term.fleetlineAsset.id} ${term.fleetlineAsset.mime??""}`:"none"}`;if(term.activeApp==="dataforge")return`Bus debug\n${fmt(term.debug??{hint:"run: bus"})}`;return"Terminal mode. Standalone desktop environments can be installed later without becoming the default shell."}
function wire(){const out=document.querySelector("#terminalOutput"),input=document.querySelector("#terminalCommand"),hint=document.querySelector("#terminalSuggestion");out?.scrollTo({top:out.scrollHeight});input?.focus();input?.addEventListener("input",()=>{term.suggestion=complete(input.value,false);hint.textContent=term.suggestion});input?.addEventListener("keydown",e=>{if(e.key==="ArrowUp"){e.preventDefault();term.historyIndex=Math.max(0,term.historyIndex-1);input.value=term.history[term.historyIndex]??input.value}else if(e.key==="ArrowDown"){e.preventDefault();term.historyIndex=Math.min(term.history.length,term.historyIndex+1);input.value=term.history[term.historyIndex]??""}else if(e.key==="Tab"){e.preventDefault();const next=complete(input.value,true);if(next)input.value=next;term.suggestion=complete(input.value,false);hint.textContent=term.suggestion}});document.querySelector("#terminalForm")?.addEventListener("submit",e=>{e.preventDefault();const command=input?.value.trim()||"";if(!command)return;term.history.push(command);term.historyIndex=term.history.length;term.suggestion="";input.value="";run(command).then(renderTerminal)})}
async function run(command){push("input",command);const[raw,...args]=command.split(/\s+/),lower=raw.toLowerCase();
 if(lower==="help"){const f=args.join(" ").trim();const list=f?COMMANDS.filter(c=>c.startsWith(f)):COMMANDS;block(["Command groups:","  lx        package/profile binding manager","  lmx       app/module launcher","  shell     DE/shell manager","  sys       runtime/system manager","  svc       services","  perm      permissions","  Lfetch    identity/neofetch","","Commands:",...list.map(c=>`  ${c}`)]);return}
 if(lower==="clear"){term.lines=[];return} if(lower==="exit"){sessionStorage.removeItem("lmi-r:user");user=null;renderLogin();return} if(lower==="reboot"){location.reload();return}
 if(raw==="Lfetch"||lower==="neofetch"){pushLfetch(buildLfetch());return} if(lower==="apps"){block(modules.map(m=>`${m.id.padEnd(10)} ${m.name} [${m.phase}]`));return}
 if(lower==="whoami"){block([`username: ${user.username}`,`cid: ${user.cid||"none"}`,`admin: ${user.is_admin?"yes":"no"}`,`home: ${user.home_path}`]);return}
 if(lower==="uptime"){push("output","session active in browser runtime");return} if(lower==="date"){const n=new Date();push("output",n.toString().replace(String(n.getFullYear()),String(n.getFullYear()+186)));return}
 if(lower==="pwd"){push("output",term.cwd);return} if(lower==="ls"){block(listFs(clamp(resolve(term.cwd,args[0]||"."))));return} if(lower==="cd"){cd(args[0]||user.home_path);return} if(lower==="cat"){cat(args[0]||"");return}
 if(lower==="touch"||lower==="mkdir"){createFs(args[0]||"",lower==="mkdir"?"dir":"file");return} if(lower==="rm"||lower==="rmdir"){removeFs(args[0]||"",lower);return}
 if(["mv","cp","open","stat"].includes(lower)){push("system",`${lower} is routed through the virtual filesystem adapter; full handler pending.`);return}
 if(lower==="lmx"&&args[0]==="open"){openApp(args[1]||"");return} if(lower==="lmx"&&args[0]==="close"){push("system",`close requested for ${args[1]||"active app"}`);return}
 if(lower==="status"||(lower==="sys"&&args[0]==="status")){block([term.statusText,`service: ${term.status?.service??"offline"}`,`version: ${term.status?.version??"unknown"}`,`database: ${term.status?.database??"unavailable"}`]);return}
 if(lower==="sys"){push("system",`sys ${args[0]||"info"}: generic runtime report available through debug commands.`);return}
 if(lower==="lx"){if(args[0]==="-v"||args[0]==="-l")block(modules.map(m=>`${m.id} ${m.name}`));else if(args[0]==="-h")block(COMMANDS.filter(c=>c.startsWith("lx ")));else push("system",`lx ${args.join(" ")} accepted by package manager shim.`);return}
 if(lower==="shell"||lower==="de"){if(args[0]==="list"||args[0]==="installed")block(term.deCatalog.map(id=>`${id}    available later`));else if(["add","remove","set","install"].includes(args[0]||""))push("system",`${args.join(" ")} queued; terminal remains base shell.`);else if(args[0]==="current")push("output","terminal");else if(args[0]==="reset")push("system","default shell reset to terminal");else block(COMMANDS.filter(c=>c.startsWith("shell ")||c.startsWith("de ")));return}
 if(["startx","stopx","tty"].includes(lower)){push("system",`${lower}: terminal remains the base interface for now.`);return}
 if(lower==="svc"||lower==="perm"){push("system",`${lower} ${args.join(" ")||"list"}: reserved for admin/runtime slice.`);return}
 if(lower==="debug"){debug(args);return} if(lower==="save"){await save(args.join(" "));return} if(lower==="asset"&&args[0]==="demo"){assetDemo();return} if(lower==="bus"){bus();return}
 if(lower==="kill"){push("system",`kill requested for ${args[0]||"active package"}`);return} if(lower==="doas"){push(user.is_admin?"system":"error",user.is_admin?"admin capability active":"doas refused: admin tag required");return}
 push("error",`Command not found: ${command}`)}
function openApp(id){if(!modules.some(m=>m.id===id)){push("error",`Unknown app: ${id||"(missing)"}`);return}term.activeApp=id;push("system",`Opened ${id} through terminal adapter.`)}
async function save(msgRaw){const msg=msgRaw.trim()||`Saved at ${new Date().toLocaleTimeString()}`;const key=`users.${user.username}.settings.demo.message`;await setState("settings",key,msg,{persist:true,scope:"user"});term.settingsValue=await getState("settings",key)||msg;term.activeApp="settings";push("system",`Persisted settings.demo.message -> ${msg}`)}
function assetDemo(){const asset={ref:"asset:demo-fleetline-preview",kind:"asset",id:"demo-fleetline-preview",mime:"image/png",size:4096};publish("sift","asset:selected",asset);term.siftNote=`Published ${asset.id}`;term.activeApp="sift";push("system",`Sift published asset:selected -> ${asset.id}`)}
function bus(){const p=packet("dataforge",Op.APP_ACTION,{action:"debug.bus"});record(p);term.debug=debugView();term.activeApp="dataforge";block([`registered modules: ${term.debug.registeredModules.length}`,`known topics: ${term.debug.knownTopics.join(", ")||"none"}`,`recent packets: ${term.debug.recentPackets.length}`,"pending requests: 0"])}
function debug(args){const what=args[0]||"modules";if(what==="modules")block(modules.map(m=>`${m.id}: ${m.capabilities.join(",")}`));else if(what==="state")block([`cwd=${term.cwd}`,`active=${term.activeApp}`,`history=${term.history.length}`]);else if(what==="reload")location.reload();else push("system",`debug ${what}: see bus command for packet view`)}
function buildLfetch(){const started=term.status?.started_at?Date.now()-term.status.started_at:performance.now(),details=[`<span class="lfetch-user">${esc(user.username)}@brokensynapse-us</span>`,'<span class="lfetch-rule">--------------------------</span>',field("OS","LMI Ver. 19.2.1.1.2212"),field("Host",`[${esc(user.cid||"acc_name")}] [${hashAccount(user.username)}]`),field("Kernel","Linux 19.2.1-22-generic"),field("Uptime",formatDuration(started)),field("Packages",`${modules.length} (lmx)`),field("Shell","fish 19.2.1"),field("Terminal","/dev/pts/0"),field("CPU","LXC Trinity 2200 (96) @ 9800 MHz"),field("GPU","JI Cashout 3301"),field("Memory","cache / 3072 GiB (cache/GiB%)"),field("Disk (/)","36.82 GiB / 245.02 GiB (<span class=\"lfetch-green\">15%</span>) - xfs"),field("Local IP (enp0s3)","reported by browser/network layer"),field("Locale",`${navigator.language||"browser"} [${Intl.DateTimeFormat().resolvedOptions().timeZone||"local"}]`),"",'<span class="lfetch-swatches"><i style="--c:#4a4a4a"></i><i style="--c:#e84242"></i><i style="--c:#12b826"></i><i style="--c:#d4b80f"></i><i style="--c:#174fe0"></i><i style="--c:#8e1fb2"></i><i style="--c:#38a2d7"></i><i style="--c:#d8d8d8"></i></span>','<span class="lfetch-swatches"><i style="--c:#777"></i><i style="--c:#ff5d5d"></i><i style="--c:#24d43a"></i><i style="--c:#fff38a"></i><i style="--c:#6285ff"></i><i style="--c:#cd18bf"></i><i style="--c:#79dde0"></i><i style="--c:#fff"></i></span>'];return`<div class="lfetch-grid"><pre>${esc(LFETCH_ART)}</pre><pre>${details.join("\n")}</pre></div>`}
function field(label,value){return`<span class="lfetch-label">${label}:</span> ${value}`}
function hashAccount(value){let h=0;for(const c of value)h=Math.imul(31,h)+c.charCodeAt(0)|0;return Math.abs(h).toString(16).padStart(5,"0").slice(0,5)}
function formatDuration(ms){const t=Math.max(0,Math.floor(ms/1e3)),h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=t%60;return h?`${h}h ${m}m ${s}s`:m?`${m}m ${s}s`:`${s}s`}
function seedFs(){const now=Date.now();["/lmi-r","/lmi-r/os","/lmi-r/os/users",user.home_path,`${user.home_path}/apps`,`${user.home_path}/home`,`${user.home_path}/tmp`].forEach(p=>{if(!term.fs.has(p))term.fs.set(p,{type:"dir",created:now})});modules.forEach(m=>{const p=`${user.home_path}/apps/${m.id}.lmx`;if(!term.fs.has(p))term.fs.set(p,{type:"file",created:now,content:`${m.name}\nphase=${m.phase}\ncapabilities=${m.capabilities.join(",")}\n`})});const profile=`${user.home_path}/profile.txt`;if(!term.fs.has(profile))term.fs.set(profile,{type:"file",created:now,content:`user=${user.username}\ncid=${user.cid}\nadmin=${user.is_admin}\nhome=${user.home_path}\n`});term.cwd=clamp(term.cwd||user.home_path)}
function cd(input){const t=clamp(resolve(term.cwd,input));if(term.fs.get(t)?.type!=="dir"){push("error",`Not a directory: ${t}`);return}term.cwd=t}
function cat(input){const t=clamp(resolve(term.cwd,input));const e=term.fs.get(t);if(!e||e.type!=="file"){push("error",`Not a file: ${t}`);return}block(String(e.content||"").split("\n"))}
function createFs(input,type){const t=clamp(resolve(term.cwd,input));if(!t||t===user.home_path||term.fs.has(t)){push("error",`Invalid path: ${t}`);return}const parent=t.split("/").slice(0,-1).join("/")||"/";if(term.fs.get(parent)?.type!=="dir"){push("error",`Parent missing: ${parent}`);return}term.fs.set(t,{type,content:"",created:Date.now()});push("system",`${type==="dir"?"mkdir":"touch"} ${t}`)}
function removeFs(input,op){const t=clamp(resolve(term.cwd,input));if(t===user.home_path){push("error","Refusing to remove home.");return}const e=term.fs.get(t);if(!e){push("error",`No such path: ${t}`);return}if(op==="rmdir"&&e.type!=="dir"){push("error",`Not a directory: ${t}`);return}term.fs.delete(t);push("system",`removed ${t}`)}
function listFs(dir){if(term.fs.get(dir)?.type!=="dir")return[`Not a directory: ${dir}`];const prefix=`${dir}/`;const names=[...term.fs.keys()].filter(p=>p.startsWith(prefix)).map(p=>p.slice(prefix.length).split("/")[0]).filter(Boolean);return[...new Set(names)].sort().map(n=>`${term.fs.get(`${dir}/${n}`)?.type==="dir"?"dir ":"file"} ${n}`)}
function resolve(cwd,input){const raw=input.startsWith("/")?input:`${cwd}/${input||"."}`;const out=[];for(const part of raw.split("/").filter(Boolean)){if(part===".")continue;if(part==="..")out.pop();else out.push(part)}return"/"+out.join("/")}
function clamp(path){if(user.is_admin)return path.startsWith("/lmi-r/os")?path:"/lmi-r/os";return path===user.home_path||path.startsWith(`${user.home_path}/`)?path:user.home_path}
function shortPwd(path){if(path===user.home_path)return"~";return path.startsWith(`${user.home_path}/`)?`~/${path.slice(user.home_path.length+1)}`:path}
function complete(v,apply){const t=v.trimStart();if(!t)return apply?"":COMMANDS.slice(0,8).join("  ");const matches=COMMANDS.filter(c=>c.toLowerCase().startsWith(t.toLowerCase()));return apply?matches.length===1?matches[0]:v:matches.slice(0,6).join("  ")}
function highlight(v){let i=0;return v.split(/(\s+)/).map(tok=>{if(/^\s+$/.test(tok))return tok;const cls=tokClass(tok,i++,v);return cls?`<span class="${cls}">${esc(tok)}</span>`:esc(tok)}).join("")}
function tokClass(tok,i,full){if(i===0)return"tok-cmd";if(tok.startsWith("-"))return"tok-flag";if(tok.startsWith("/")||tok.startsWith("~/")||tok===".."||tok===".")return"tok-path";if(i===1&&/^(lx|shell|lmx|sys|svc|perm|debug|de)$/.test(full.split(/\s+/)[0]||""))return"tok-subcmd";if(/^[a-z0-9._-]+\.lmx$/i.test(tok)||/^(settings|sift|fleetline|dataforge)$/i.test(tok))return"tok-app";return""}
function push(kind,text){term.lines.push({kind,text});if(term.lines.length>160)term.lines.splice(0,term.lines.length-160)}
function block(lines){lines.forEach(line=>push("output",line))}
function pushLfetch(html){term.lines.push({kind:"lfetch",text:html});if(term.lines.length>160)term.lines.splice(0,term.lines.length-160)}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function fmt(v,indent=0){const pad=" ".repeat(indent);if(v==null)return String(v);if(Array.isArray(v))return v.length?v.map((x,i)=>`${pad}${i}: ${fmt(x,indent+2).trimStart()}`).join("\n"):"[]";if(typeof v==="object"){const e=Object.entries(v);return e.length?e.map(([k,x])=>`${pad}${k}: ${typeof x==="object"&&x!==null?"\n"+fmt(x,indent+2):fmt(x,0)}`).join("\n"):"{}"}return String(v)}
function loadUser(){try{const v=sessionStorage.getItem("lmi-r:user");return v?fromB64(v):null}catch{sessionStorage.removeItem("lmi-r:user");return null}}
async function bootTerminal(){subscribe("asset:selected",asset=>{term.fleetlineAsset=asset;push("system",`Fleetline received asset:selected -> ${asset.id}`);renderTerminal()});seedFs();renderTerminal();try{const r=await fetch("/api-r/status",{headers:{Accept:"application/json"},cache:"no-store"});const body=await r.json();if(!r.ok)throw new Error(body.error||`API request failed: ${r.status}`);term.status=body;term.statusText="Rust backend online";term.settingsValue=await getState("settings",`users.${user.username}.settings.demo.message`)||"No persisted value yet.";push("system","Connected to /api-r. Packet persistence is available.")}catch(error){term.statusText=`Rust backend unavailable: ${String(error)}`;push("error",term.statusText)}renderTerminal()}
if(user)bootTerminal();else renderLogin();
